use std::fs
use std::json

struct Item {
    sku: string,
    qty: int,
    price: float,
}

struct Order {
    id: int,
    customer: string,
    items: Vec<Item>,
    note: Option<string>,
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let parsed = json.parse_string::<Vec<Order>>(text)
    match parsed {
        Ok(orders) => {
            let mut names: Vec<string> = []
            let mut sums: Vec<float> = []
            for o in orders {
                let mut sub = 0.0
                for it in o.items {
                    sub += (it.qty as float) * it.price
                }
                let mut found = false
                let mut i = 0
                while i < names.len() {
                    if names[i] == o.customer {
                        sums[i] = sums[i] + sub
                        found = true
                    }
                    i += 1
                }
                if !found {
                    names.push(o.customer)
                    sums.push(sub)
                }
            }
            let mut idx: Vec<int> = []
            let mut k = 0
            while k < names.len() {
                idx.push(k as int)
                k += 1
            }
            idx.sort_by(|a, b| names[*a as usize].cmp(names[*b as usize]))
            for j in idx {
                let n = names[j as usize]
                let v = sums[j as usize]
                println("${n} ${v:.2}")
            }
        }
        Err(_) => {
            println("invalid input")
            std::process::exit(1)
        }
    }
}

